def summarize(rows):
    summary = {}
    for row in rows:
        region = row.get('region')
        revenue = row.get('revenue')

        if region is None:
            continue

        try:
            # Revenue might be a string representing a number
            numeric_revenue = float(revenue)
        except (ValueError, TypeError):
            # Ignore rows with missing or unparseable revenue
            continue

        if region in summary:
            summary[region] += numeric_revenue
        else:
            summary[region] = numeric_revenue

    return summary

