import pytest
from summarize import summarize

def test_basic_summary():
    rows = [
        {'region': 'A', 'revenue': '100.5'},
        {'region': 'B', 'revenue': 200},
        {'region': 'A', 'revenue': '50.25'}
    ]
    expected = {'A': 150.75, 'B': 200.0}
    assert summarize(rows) == expected

def test_empty_input():
    rows = []
    expected = {}
    assert summarize(rows) == expected

def test_missing_region():
    rows = [
        {'region': 'A', 'revenue': 100},
        {'revenue': 200}  # Missing region
    ]
    expected = {'A': 100.0}
    assert summarize(rows) == expected

def test_unparseable_revenue():
    rows = [
        {'region': 'A', 'revenue': 100},
        {'region': 'B', 'revenue': 'abc'}, # Unparseable
        {'region': 'A', 'revenue': '200 units'} # Unparseable
    ]
    expected = {'A': 100.0}
    assert summarize(rows) == expected

def test_mixed_types_and_missing_data():
    rows = [
        {'region': 'A', 'revenue': '50'},
        {'region': 'A', 'revenue': '100'},
        {'region': 'B', 'revenue': None}, # None revenue
        {'region': 'B', 'revenue': 300}
    ]
    expected = {'A': 150.0, 'B': 300.0}
    assert summarize(rows) == expected

def test_all_invalid():
    rows = [
        {'region': 'A', 'revenue': None},
        {'region': 'A'}, # Missing revenue key
        {'region': 'A', 'revenue': 'xyz'}
    ]
    expected = {}
    assert summarize(rows) == expected

